const acc = $('Get Account').first().json;
const mail = $('When Called by Stub').first();
const j = mail.json;

if (!acc?.account_id) {
  throw new Error('Nema account_id za ACCOUNT_EMAIL=' + (j.ACCOUNT_EMAIL || '?'));
}

function header(name) {
  const h = j.headers || j.metadata || {};
  const key = Object.keys(h).find(k => k.toLowerCase() === name.toLowerCase());
  return key ? h[key] : null;
}
function pickAngle(s) {
  if (!s) return null;
  const m = String(s).match(/<([^>]+)>/);
  return m ? m[1].toLowerCase() : String(s).trim().toLowerCase();
}
function parseFrom(obj) {
  if (obj.from?.value?.[0]?.address) return String(obj.from.value[0].address).trim().toLowerCase();
  if (typeof obj.from === 'string') return obj.from.trim().toLowerCase();
  return 'unknown@unknown';
}
function threadKey(obj) {
  const inReply = pickAngle(header('in-reply-to') || obj.inReplyTo);
  if (inReply) return inReply;
  const refs = String(header('references') || obj.references || '');
  const rm = refs.match(/<([^>]+)>/);
  if (rm) return rm[1].toLowerCase();
  const mid = pickAngle(header('message-id') || obj.messageId);
  if (mid) return mid;
  const u = obj.attributes?.uid ?? obj.uid ?? 'unknown';
  return 'uid-' + u;
}
function toIsoDate(raw) {
  if (raw == null || raw === '') return null;
  if (raw instanceof Date && !Number.isNaN(raw.getTime())) return raw.toISOString();
  let s = String(raw).trim();
  s = s.replace(/\s*\([^)]*\)\s*$/g, '').trim();
  const d = new Date(s);
  if (Number.isNaN(d.getTime())) return null;
  return d.toISOString();
}

const uid = j.attributes?.uid ?? j.uid;
const binary = mail.binary ?? {};
const isoDate = toIsoDate(j.date ?? header('date'));
const folder = 'INBOX';
const external_id = 'imap:' + folder + ':uid-' + uid;

return [{
  json: {
    account_id: acc.account_id,
    account_email: j.ACCOUNT_EMAIL,
    from_address: parseFrom(j),
    subject: j.subject ?? '',
    textPlain: j.textPlain ?? j.text ?? '',
    textHtml: j.textHtml ?? '',
    uid,
    imap_uid: uid != null ? Number(uid) : null,
    folder,
    date: isoDate,
    received_at: isoDate,
    external_id,
    thread_key: threadKey(j),
    mode: 'live',
    has_attachments: Object.keys(binary).length > 0
  },
  binary,
  pairedItem: { item: 0 }
}];

