const mail = $('Normalize Mail (Live)').first().json;
const msg = $('Insert Message').first().json;
const model = $env.OLLAMA_MODEL || 'llama3.1:8b';
const url = ($env.OLLAMA_URL || 'http://127.0.0.1:11434').replace(/\/$/, '');
const body = (mail.textPlain || '').slice(0, 6000);
const prompt = `Analiziraj dolazni email na hrvatskom. Vrati SAMO JSON: {\"summary\":\"...\",\"priority\":\"low|normal|high|urgent\",\"draft_reply\":\"...\"}\n\nOd: ${mail.from_address}\nPredmet: ${mail.subject}\n\n${body}`;

try {
  const resp = await fetch(`${url}/api/generate`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ model, prompt, stream: false, format: 'json', options: { temperature: 0.2 } })
  });
  const data = await resp.json();
  const raw = data.response || '{}';
  const ai = JSON.parse(raw.match(/\{[\s\S]*\}/)?.[0] || raw);
  const priority = ['low','normal','high','urgent'].includes(String(ai.priority || '').toLowerCase()) ? String(ai.priority).toLowerCase() : 'normal';
  const summary = String(ai.summary || ai.title || ai.text || '').slice(0, 4000) || (`Predmet: ${mail.subject || ''}`).slice(0, 4000);
  return [{ json: {
    message_id: msg.message_id,
    ai_summary: summary,
    ai_priority: priority,
    ai_draft: String(ai.draft_reply || ai.draft || '').slice(0, 8000),
    account_id: mail.account_id,
    has_attachments: !!mail.has_attachments
  }, pairedItem: { item: 0 } }];
} catch (e) {
  return [{ json: {
    message_id: msg.message_id,
    ai_summary: mail.subject ? (`Predmet: ${mail.subject}`).slice(0, 4000) : null,
    ai_priority: 'normal',
    ai_draft: null,
    ai_error: String(e.message || e),
    account_id: mail.account_id,
    has_attachments: !!mail.has_attachments
  }, pairedItem: { item: 0 } }];
}

const msg = $('Insert Message').first().json;
const mail = $('Normalize Mail (Live)').first();
const binary = mail.binary || {};
const accountId = mail.json.account_id;
const messageId = msg.message_id || msg.id;
const entries = Object.entries(binary);
if (!entries.length) return [];

// Host (DB + SSH mkdir): /var/lib/oriphiel/attachments
// n8n Docker Write File: /data/attachments (volume mount)
const HOST_ROOT = '/var/lib/oriphiel/attachments/email';
const N8N_ROOT = '/data/attachments/email';

return entries.map(([key, file]) => {
  const sizeNum = Number(file.fileSize);
  const filename = String(file.fileName || key || 'attachment.bin').replace(/[\\/]/g, '_');
  const rel = `${accountId}/${messageId}_${filename}`;
  return {
    json: {
      message_id: messageId,
      filename,
      mimeType: file.mimeType || 'application/octet-stream',
      fileSize: Number.isFinite(sizeNum) ? Math.round(sizeNum) : 0,
      storage_path: `${HOST_ROOT}/${rel}`,
      write_path: `${N8N_ROOT}/${rel}`,
      account_id: accountId
    },
    binary: { data: file },
    pairedItem: { item: 0 }
  };
});

